SELECT ID, YT_VIDEO_ID, TITULO, DURACAO_SEG, TIPO, ORIGEM, PROGRESSO_SEG, TEM_MENTOR FROM (SELECT V.ID, V.YT_VIDEO_ID, V.TITULO, V.DURACAO_SEG, V.TIPO, V.ORIGEM, V.PROGRESSO_SEG, C.TEM_MENTOR, V.PRIORIDADE, V.ORDEM, C.ID CANAL_ORDEM, ROW_NUMBER() OVER (PARTITION BY V.CANAL_ID ORDER BY V.PRIORIDADE DESC, V.ORDEM ASC) AS VEZ FROM VIDEOS V JOIN CANAIS C ON C.ID = V.CANAL_ID WHERE (V.STATUS = 'FILA' OR (V.STATUS = 'ESTUDADO' AND V.PRIORIDADE = 2)) AND C.CARGA_STATUS <> 'LISTANDO' AND ({{audio}} = 1 OR V.ORIGEM IS NULL OR V.ORIGEM <> 'AUDIO' OR V.PROGRESSO_SEG >= V.DURACAO_SEG) AND ({{canalId}} = 0 OR V.CANAL_ID = {{canalId}})) X ORDER BY PRIORIDADE DESC, (ORIGEM = 'AUDIO') ASC, CANAL_ORDEM ASC, ORDEM ASC LIMIT 1